parts.text:
{
  "units": [
    {
      "quote": "29 CFR 825.110 — Eligible employee.",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "Provides the section heading for 29 CFR 825.110, identifying the topic as eligible employees without imposing substantive rights or duties."
    },
    {
      "quote": "An eligible employee is an employee of a covered employer who:\n\n(1) Has been employed by the employer for at least 12 months, and\n\n(2) Has been employed for at least 1,250 hours of service during the 12-month period immediately preceding the commencement of the leave ( see § 825.801 for special hours of service requirements for airline flight crew employees), and\n\n(3) Is employed at a worksite where 50 or more employees are employed by the employer within 75 miles of that worksite.",
      "scope_quotes": [
        "(a) An eligible employee is an employee of a covered employer who:"
      ],
      "kind": "definition",
      "meaning": "Defines an eligible employee as an employee of a covered employer who satisfies all three cumulative conditions: being employed by the employer for at least 12 months, being employed for at least 1,250 hours of service during the 12-month period immediately prior to the start of leave (subject to § 825.801 for airline flight crew employees), and working at a worksite where the employer employs 50 or more employees within 75 miles."
    },
    {
      "quote": "See § 825.105(b) regarding employees who work outside the U.S.",
      "scope_quotes": [
        "(a) An eligible employee is an employee of a covered employer who:",
        "(3) Is employed at a worksite where 50 or more employees are employed by the employer within 75 miles of that worksite."
      ],
      "kind": "background",
      "meaning": "Directs readers to cross-reference § 825.105(b) for rules governing employees working outside the United States without adding substantive provisions directly here."
    },
    {
      "quote": "The 12 months an employee must have been employed by the employer need not be consecutive months, provided",
      "scope_quotes": [],
      "kind": "permission",
      "meaning": "Permits the 12 months of employment required for FMLA eligibility to be non-consecutive, provided the conditions and rules in paragraph (b) are met."
    },
    {
      "quote": "Subject to the exceptions provided in paragraph (b)(2) of this section, employment periods prior to a break in service of seven years or more need not be counted in determining whether the employee has been employed by the employer for at least 12 months.",
      "scope_quotes": [
        "(b) The 12 months an employee must have been employed by the employer need not be consecutive months, provided"
      ],
      "kind": "exemption",
      "meaning": "Exempts employers from having to count employment periods prior to a break in service of seven years or more when determining whether an employee has reached 12 months of employment, subject to the exceptions in paragraph (b)(2)."
    },
    {
      "quote": "The employee's break in service is occasioned by the fulfillment of his or her Uniformed Services Employment and Reemployment Rights Act (USERRA), 38 U.S.C. 4301, et seq., covered service obligation.",
      "scope_quotes": [
        "(b) The 12 months an employee must have been employed by the employer need not be consecutive months, provided",
        "(2) Employment periods preceding a break in service of more than seven years must be counted in determining whether the employee has been employed by the employer for at least 12 months where:"
      ],
      "kind": "condition",
      "meaning": "Specifies that an employer must count employment periods preceding a break in service of more than seven years toward the 12-month employment threshold if the break was caused by the fulfillment of a USERRA-covered service obligation."
    },
    {
      "quote": "The period of absence from work due to or necessitated by USERRA-covered service must be also counted in determining whether the employee has been employed for at least 12 months by the employer.",
      "scope_quotes": [
        "(b) The 12 months an employee must have been employed by the employer need not be consecutive months, provided",
        "(2) Employment periods preceding a break in service of more than seven years must be counted in determining whether the employee has been employed by the employer for at least 12 months where:",
        "(i) The employee's break in service is occasioned by the fulfillment of his or her Uniformed Services Employment and Reemployment Rights Act (USERRA), 38 U.S.C. 4301, et seq., covered service obligation."
      ],
      "kind": "requirement",
      "meaning": "Mandates that any period of absence from work caused by or necessitated by USERRA-covered service must also be counted toward the 12-month employment eligibility requirement."
    },
    {
      "quote": "However, this section does not provide any greater entitlement to the employee than would be available under the USERRA; or",
      "scope_quotes": [
        "(b) The 12 months an employee must have been employed by the employer need not be consecutive months, provided",
        "(2) Employment periods preceding a break in service of more than seven years must be counted in determining whether the employee has been employed by the employer for at least 12 months where:",
        "(i) The employee's break in service is occasioned by the fulfillment of his or her Uniformed Services Employment and Reemployment Rights Act (USERRA), 38 U.S.C. 4301, et seq., covered service obligation."
      ],
      "kind": "statement",
      "meaning": "Clarifies that this section does not confer any entitlement on an employee beyond what is available under USERRA."
    },
    {
      "quote": "A written agreement, including a collective bargaining agreement, exists concerning the employer's intention to rehire the employee after the break in service (e.g., for purposes of the employee furthering his or her education or for childrearing purposes).",
      "scope_quotes": [
        "(b) The 12 months an employee must have been employed by the employer need not be consecutive months, provided",
        "(2) Employment periods preceding a break in service of more than seven years must be counted in determining whether the employee has been employed by the employer for at least 12 months where:"
      ],
      "kind": "condition",
      "meaning": "Specifies that an employer must count employment periods preceding a break in service of more than seven years toward the 12-month employment threshold if there is a written agreement (such as a collective bargaining agreement) showing the employer's intention to rehire the employee after the break (e.g., for education or childrearing)."
    },
    {
      "quote": "If an employee is maintained on the payroll for any part of a week, including any periods of paid or unpaid leave (sick, vacation) during which other benefits or compensation are provided by the employer (e.g., workers' compensation, group health plan benefits, etc.), the week counts as a week of employment.",
      "scope_quotes": [
        "(b) The 12 months an employee must have been employed by the employer need not be consecutive months, provided"
      ],
      "kind": "requirement",
      "meaning": "Dictates that if an employee is on the payroll for any part of a calendar week—including paid or unpaid leave periods where benefits or compensation like group health or workers' compensation are provided—that entire week must be counted as a week of employment."
    },
    {
      "quote": "For purposes of determining whether intermittent/occasional/casual employment qualifies as at least 12 months, 52 weeks is deemed to be equal to 12 months.",
      "scope_quotes": [
        "(b) The 12 months an employee must have been employed by the employer need not be consecutive months, provided"
      ],
      "kind": "definition",
      "meaning": "Establishes that for intermittent, occasional, or casual employment, reaching 52 weeks of employment is deemed legally equivalent to completing 12 months."
    },
    {
      "quote": "Nothing in this section prevents employers from considering employment prior to a continuous break in service of more than seven years when determining whether an employee has met the 12-month employment requirement.",
      "scope_quotes": [
        "(b) The 12 months an employee must have been employed by the employer need not be consecutive months, provided"
      ],
      "kind": "permission",
      "meaning": "Permits employers voluntarily to credit an employee's employment prior to a continuous break in service of more than seven years toward the 12-month requirement even when not legally compelled to do so."
    },
    {
      "quote": "However, if an employer chooses to recognize such prior employment, the employer must do so uniformly, with respect to all employees with similar breaks in service.",
      "scope_quotes": [
        "(b) The 12 months an employee must have been employed by the employer need not be consecutive months, provided",
        "(4) Nothing in this section prevents employers from considering employment prior to a continuous break in service of more than seven years when determining whether an employee has met the 12-month employment requirement."
      ],
      "kind": "requirement",
      "meaning": "Requires an employer that voluntarily recognizes employment prior to a continuous break in service of more than seven years to apply that policy uniformly across all employees with similar breaks in service."
    },
    {
      "quote": "Except as provided in paragraph (c)(2) of this section and in § 825.801 containing the special hours of service requirement for airline flight crew employees, whether an employee has worked the minimum 1,250 hours of service is determined according to the principles established under the Fair Labor Standards Act (FLSA) for determining compensable hours of work. See 29 CFR part 785.",
      "scope_quotes": [
        "(c)(1)"
      ],
      "kind": "requirement",
      "meaning": "Requires that the determination of whether an employee has worked the minimum 1,250 hours of service be made according to FLSA principles for compensable hours of work (referencing 29 CFR part 785), except as provided under paragraph (c)(2) for USERRA service and § 825.801 for airline flight crew employees."
    },
    {
      "quote": "The determining factor is the number of hours an employee has worked for the employer within the meaning of the FLSA. The determination is not limited by methods of recordkeeping, or by compensation agreements that do not accurately reflect all of the hours an employee has worked for or been in service to the employer. Any accurate accounting of actual hours worked under FLSA's principles may be used.",
      "scope_quotes": [
        "(c)(1)"
      ],
      "kind": "statement",
      "meaning": "Clarifies that the hours determination turns on actual hours worked under the FLSA, is not restricted by incomplete recordkeeping methods or inaccurate compensation agreements, and may utilize any accurate accounting of actual hours worked."
    },
    {
      "quote": "An employee returning from USERRA-covered service shall be credited with the hours of service that would have been performed but for the period of absence from work due to or necessitated by USERRA-covered service in determining the employee's eligibility for FMLA-qualifying leave.",
      "scope_quotes": [
        "(c)(2)"
      ],
      "kind": "requirement",
      "meaning": "Requires employers to credit an employee returning from USERRA-covered service with the hours of service that would have been worked but for the absence caused by or necessitated by USERRA-covered service when determining eligibility for FMLA leave."
    },
    {
      "quote": "Accordingly, a person reemployed following USERRA-covered service has the hours that would have been worked for the employer added to any hours actually worked during the previous 12-month period to meet the hours of service requirement.",
      "scope_quotes": [
        "(c)(2)"
      ],
      "kind": "requirement",
      "meaning": "Mandates that for a person reemployed following USERRA-covered service, the hours that would have been worked must be added to hours actually worked during the preceding 12-month period to determine whether the 1,250 hours threshold is satisfied."
    },
    {
      "quote": "In order to determine the hours that would have been worked during the period of absence from work due to or necessitated by USERRA-covered service, the employee's pre-service work schedule can generally be used for calculations. See § 825.801(c) for special rules applicable to airline flight crew employees.",
      "scope_quotes": [
        "(c)(2)"
      ],
      "kind": "permission",
      "meaning": "Permits calculations of the hours that would have been worked during USERRA-covered absence to generally rely on the employee's pre-service work schedule, subject to special rules in § 825.801(c) for airline flight crew employees."
    },
    {
      "quote": "In the event an employer does not maintain an accurate record of hours worked by an employee, including for employees who are exempt from FLSA's requirement that a record be kept of their hours worked (e.g., bona fide executive, administrative, and professional employees as defined in FLSA Regulations, 29 CFR part 541), the employer has the burden of showing that the employee has not worked the requisite hours.",
      "scope_quotes": [
        "(c)(3)"
      ],
      "kind": "requirement",
      "meaning": "Places the burden of proof on the employer to demonstrate that an employee has not worked the required 1,250 hours whenever the employer fails to maintain an accurate record of the employee's hours worked, including for FLSA-exempt executive, administrative, and professional staff."
    },
    {
      "quote": "An employer must be able to clearly demonstrate, for example, that full-time teachers ( see § 825.102 for definition) of an elementary or secondary school system, or institution of higher education, or other educational establishment or institution (who often work outside the classroom or at their homes) did not work 1,250 hours during the previous 12 months in order to claim that the teachers are not eligible for FMLA leave. See § 825.801(d) for special rules applicable to airline flight crew employees.",
      "scope_quotes": [
        "(c)(3)"
      ],
      "kind": "requirement",
      "meaning": "Requires an employer to clearly demonstrate that full-time teachers at educational institutions did not work 1,250 hours during the prior 12 months to deny them FMLA eligibility on hours grounds, noting teachers often work outside classrooms or at home, and cross-referencing § 825.801(d) for airline flight crew rules."
    },
    {
      "quote": "The determination of whether an employee meets the hours of service requirement and has been employed by the employer for a total of at least 12 months must be made as of the date the FMLA leave is to start.",
      "scope_quotes": [
        "(d)"
      ],
      "kind": "requirement",
      "meaning": "Mandates that determinations of whether an employee meets the 1,250 hours of service requirement and the 12-month employment tenure requirement must be made as of the specific date the FMLA leave is scheduled to begin."
    },
    {
      "quote": "An employee may be on non-FMLA leave at the time he or she meets the 12-month eligibility requirement, and in that event, any portion of the leave taken for an FMLA-qualifying reason after the employee meets the eligibility requirement would be FMLA leave. See § 825.300(b) for rules governing the content of the eligibility notice given to employees.",
      "scope_quotes": [
        "(d)"
      ],
      "kind": "permission",
      "meaning": "Permits an employee to be on non-FMLA leave when reaching the 12-month eligibility threshold, and classifies any subsequent portion of leave taken for an FMLA-qualifying reason after meeting that threshold as FMLA leave, cross-referencing § 825.300(b) for eligibility notice content rules."
    },
    {
      "quote": "Whether 50 employees are employed within 75 miles to ascertain an employee's eligibility for FMLA benefits is determined when the employee gives notice of the need for leave.",
      "scope_quotes": [
        "(e)"
      ],
      "kind": "requirement",
      "meaning": "Requires that the 50 employees within 75 miles eligibility condition be determined at the point in time when the employee gives notice of the need for leave."
    },
    {
      "quote": "Whether the leave is to be taken at one time or on an intermittent or reduced leave schedule basis, once an employee is determined eligible in response to that notice of the need for leave, the employee's eligibility is not affected by any subsequent change in the number of employees employed at or within 75 miles of the employee's worksite, for that specific notice of the need for leave.",
      "scope_quotes": [
        "(e)"
      ],
      "kind": "statement",
      "meaning": "Provides that whether leave is taken continuously, intermittently, or on a reduced schedule, once an employee is determined eligible based on notice, that eligibility is unaffected by subsequent changes in the 50-employee headcount within 75 miles for that specific leave notice."
    },
    {
      "quote": "Similarly, an employer may not terminate employee leave that has already started if the employee count drops below 50.",
      "scope_quotes": [
        "(e)"
      ],
      "kind": "prohibition",
      "meaning": "Prohibits an employer from terminating an employee's FMLA leave that is already underway if the employer's employee headcount drops below 50."
    },
    {
      "quote": "For example, if an employer employs 60 employees in August, but expects that the number of employees will drop to 40 in December, the employer must grant FMLA benefits to an otherwise eligible employee who gives notice of the need for leave in August for a period of leave to begin in December.",
      "scope_quotes": [
        "(e)"
      ],
      "kind": "requirement",
      "meaning": "Illustrates that an employer must grant FMLA benefits to an otherwise eligible employee who gives notice in August (when 60 employees are employed) for leave beginning in December, even if the employer expects headcount to fall to 40 by December."
    }
  ]
}
